#[cfg(test)]
mod tests {
    #[test]
    fn all_emoji_decode() {
        for (cat, list) in super::CATEGORIES {
            assert!(!list.is_empty(), "{cat}");
            for e in *list { let img = image::load_from_memory(e.png).unwrap_or_else(|err| panic!("{}: {err}", e.name)); assert_eq!(img.width(), 128); }
        }
    }
}
